"""ECG findings (tier 0.5i).

Edit freely — see data/__init__.py for how files are loaded."""


_ECG_FINDINGS = {
    'st elevation': 'ST Elevation — J point and ST segment elevated ≥1mm in limb leads, ≥2mm in V1-V4 (≥2.5mm in men <40); causes: STEMI (convex/tombstone), pericarditis (diffuse, concave, saddle-shaped), Brugada (V1-V2 coved), early repolarization (concave, notching at J point), LVH, LBBB; STEMI: reciprocal ST depression in opposite leads',
    'st depression': 'ST Depression — J point depression ≥1mm from baseline; causes: NSTEMI/unstable angina (horizontal/downsloping), demand ischemia, reciprocal changes (in STEMI territory), digoxin effect (scooping/sagging), LVH with strain, hypokalemia; horizontal/downsloping worse than upsloping',
    'stemi': 'STEMI (ST-Elevation MI) — culprit artery by territory: anterior (LAD) = V1-V4; lateral (LCx or diagonal) = I, aVL, V5-V6; inferior (RCA 80%, LCx 20%) = II, III, aVF; posterior (RCA/LCx) = ST depression V1-V2 + tall R; RV MI with inferior STEMI: ST elevation in V4R; tx: primary PCI (goal door-to-balloon <90 min)',
    't wave inversion': 'T Wave Inversion — normal in aVR, V1; abnormal: symmetric deep inversions (Wellens pattern in V2-V3 = critical LAD stenosis); diffuse: PE (right heart strain), myocarditis; diffuse ± prolonged QT: intracranial hypertension (giant T wave inversions); persistent V1-V4: ARVC, anterior ischemia',
    'peaked t waves': 'Peaked T Waves — tall, narrow, symmetric T waves; classic sign of hyperkalemia (earliest ECG change; K+ 5.5-6.5 mEq/L); also: early STEMI (hyperacute T waves), LVH, normal variant in young athletes; progression in hyperkalemia: peaked T → PR prolongation → wide QRS → sine wave → VF',
    't wave flattening': 'T Wave Flattening/Inversion — hypokalemia: flat/inverted T waves + prominent U waves; ischemia; digoxin effect; LVH with strain; hypothyroidism; also normal variant in V1-V3 especially in women and Black patients',
    'qt prolongation': 'QTc Prolongation — corrected QT >440ms (men) or >460ms (women); ↑risk torsades de pointes → VF; congenital: LQTS types 1-3; acquired (MCC): drugs (antiarrhythmics, antipsychotics, fluoroquinolones, macrolides, methadone, ondansetron), electrolytes (↓K+, ↓Mg²⁺, ↓Ca²⁺), hypothyroidism, intracranial hemorrhage',
    'pr prolongation': 'PR Prolongation — PR interval >200ms; first-degree AV block; causes: increased vagal tone, inferior MI, myocarditis, electrolyte abnormalities, digoxin, beta blockers, CCBs; asymptomatic, no treatment needed unless causing symptoms or progressing',
    'short pr interval': 'Short PR Interval — PR <120ms; causes: WPW syndrome (delta wave, wide QRS), LGL syndrome (no delta wave, no wide QRS), junctional rhythm, high sympathetic tone; WPW: accessory pathway bypasses AV node → pre-excitation',
    'first degree av block': 'First-Degree AV Block — PR interval >200ms; every P wave conducts; causes: vagal tone, inferior MI, myocarditis, digoxin, BB, CCB; benign in isolation; no treatment',
    'wenckebach': 'Wenckebach (Mobitz Type I AV Block) — progressive PR prolongation → dropped QRS → cycle repeats; site: AV node; causes: inferior MI (RCA), increased vagal tone, myocarditis; generally benign; rarely needs pacing unless symptomatic',
    'mobitz type 1': 'Mobitz Type I (Wenckebach) — progressive PR lengthening then dropped beat; AV nodal block; inferior MI (RCA); benign; monitor for progression; atropine if symptomatic',
    'mobitz type 2': 'Mobitz Type II AV Block — constant PR interval with sudden non-conducted P waves; infranodal block (His-Purkinje); anterior MI (LAD); unpredictable → complete heart block; REQUIRES PACING even if asymptomatic; wide QRS often',
    'complete heart block': 'Complete (Third-Degree) AV Block — complete AV dissociation; P waves and QRS complexes independent; escape rhythm: junctional (narrow, 40-60 bpm) or ventricular (wide, 20-40 bpm); causes: inferior MI (reversible), anterior MI (poor prognosis), Lyme disease, sarcoidosis, digoxin toxicity; tx: ATROPINE if unstable → temporary pacing → permanent pacemaker',
    'third degree heart block': 'Third-Degree (Complete) AV Block — no conduction from atria to ventricles; P-P and R-R regular but independent; ventricular escape rhythm; causes: inferior MI (junctional escape, usually reversible with atropine), anterior MI (ventricular escape, poor prognosis), Lyme, sarcoidosis; requires pacing',
    'lbbb': 'Left Bundle Branch Block — QRS ≥120ms + broad monophasic R in I, aVL, V5-V6 + rS or QS in V1; causes: ischemia (LAD territory), cardiomyopathy, HTN, LBBB + acute chest pain = STEMI equivalent (Sgarbossa criteria); new LBBB alone is no longer treated as a STEMI equivalent (ACC/AHA 2013); electrical alternans absent; T waves discordant',
    'rbbb': "Right Bundle Branch Block — QRS ≥120ms + RSR' (rabbit ears) in V1-V2 + wide S wave in I, V5-V6; causes: RV strain (PE, pulmonary HTN), anterior MI, ASD, ARVC, idiopathic; new RBBB with anterior MI = poor prognosis; S1Q3T3 pattern suggests PE",
    'left anterior fascicular block': 'Left Anterior Fascicular Block (LAFB) — left axis deviation (-45° to -90°) + qR in I, aVL + rS in II, III, aVF; incomplete block of anterior fascicle; common in anterior MI, HTN, cardiomyopathy; QRS usually normal width unless combined with RBBB (bifascicular block)',
    'delta wave': 'Delta Wave — slurred upstroke of QRS in WPW syndrome; pre-excitation via accessory pathway (Bundle of Kent) bypassing AV node; short PR + delta wave + wide QRS + secondary ST-T changes; risk: atrial fibrillation with rapid conduction → VF → sudden death; AVOID adenosine, digoxin, CCBs in AF with WPW; tx: ablation',
    'brugada pattern': 'Brugada Pattern/Syndrome — type 1 (diagnostic): coved ST elevation ≥2mm with downward T wave in V1-V2 (± V3); type 2: saddle-back ST elevation; sodium channelopathy (SCN5A); risk: VF and sudden cardiac death especially during sleep/fever; male predominance; fever unmasks pattern; tx: ICD; quinidine; avoid sodium channel blockers',
    'epsilon wave': 'Epsilon Wave — small positive deflection after QRS in V1-V3; pathognomonic for ARVC (Arrhythmogenic Right Ventricular Cardiomyopathy); caused by delayed RV activation through scar; also: T wave inversions in V1-V4, RBBB morphology VT; fatty infiltration of RV; dx: MRI; ↑risk SCD in young athletes',
    'osborn wave': 'Osborn Wave (J Wave) — positive deflection at J point (QRS-ST junction) most prominent in V4-V6; pathognomonic for hypothermia (core temp <30°C); also: hypercalcemia, early repolarization; Osborn wave amplitude correlates with degree of hypothermia; shivering artifact; tx: active rewarming',
    'torsades de pointes': 'Torsades de Pointes — polymorphic VT with QRS complexes twisting around isoelectric line; precipitated by prolonged QTc (congenital or acquired); triggers: pauses, bradycardia, hypokalemia/hypomagnesemia; tx: IV magnesium sulfate 2g (first-line), correct electrolytes, overdrive pacing, isoproterenol; defibrillation if pulseless; remove offending drugs',
    'electrical alternans': 'Electrical Alternans — alternating QRS amplitude (P, QRS, T all alternate); classic sign of large pericardial effusion/cardiac tamponade (swinging motion of heart in fluid); also: alternating LBBB, severe cardiomegaly; if tamponade suspected: stat echo + pericardiocentesis',
    'sgarbossa criteria': 'Sgarbossa Criteria — ECG diagnosis of STEMI in setting of LBBB or pacemaker; criterion 1: concordant ST elevation ≥1mm in leads with positive QRS (most specific, score 5); criterion 2: concordant ST depression ≥1mm in V1-V3 (score 3); criterion 3: discordant ST elevation ≥5mm (score 2); score ≥3 = STEMI likely; modified: ratio-based criterion 3 (ST/S ≤-0.25)',
    's1q3t3': 'S1Q3T3 Pattern — prominent S wave in lead I + Q wave in lead III + T wave inversion in lead III; classic pattern of acute cor pulmonale/pulmonary embolism; low sensitivity (~20%) but high specificity when present; other PE findings: sinus tachycardia (MCC), new RBBB, right axis deviation, T inversions V1-V4',
    'sokolow-lyon criteria': 'Sokolow-Lyon Criteria — LVH on ECG: S wave in V1 + R wave in V5 or V6 ≥35mm; or R in aVL ≥11mm; limited sensitivity (~50%) but high specificity (~90%); strain pattern (asymmetric ST depression + T inversion in lateral leads) suggests pressure overload; Cornell criteria: R in aVL + S in V3 >28mm (men) or >20mm (women)',
    'early repolarization': 'Early Repolarization — J point elevation (notching or slurring) with concave ST elevation, most prominent in V4-V6 and inferior leads; common in young athletic males; traditionally benign; recent data: inferior + lateral early repolarization may ↑risk VF/sudden death; QRS notching more concerning than slurring',
    'pericarditis ecg': 'Pericarditis ECG Changes — 4 stages: Stage 1 (acute, days 1-2): diffuse ST elevation (saddle-shaped/concave up) in almost all leads EXCEPT aVR (ST depression) and V1 + PR depression (virtually pathognomonic); Stage 2 (1-3 weeks): ST normalizes, PR depression persists; Stage 3: T wave inversions develop; Stage 4 (weeks-months): ECG normalizes or persists',
    'digoxin effect': 'Digoxin Effect — scooping/sagging ST depression (reverse-tick appearance), shortened QT, T wave inversion or flattening, ↑PR interval, ↑AV block; not the same as digoxin toxicity (which causes arrhythmias); toxicity: early-life-threatening: PVCs (bigeminy), slow VT; toxicity triggers: hypokalemia, hypomagnesemia, renal failure',
    'hyperkalemia ecg': 'Hyperkalemia ECG Progression — K+ ~5.5: peaked narrow T waves (tented); K+ ~6.5: ↑PR + ↑QRS; K+ ~7: wide QRS + P wave disappears; K+ ~8-9: sine wave pattern → VF; tx: Ca²⁺ gluconate (membrane stabilization, immediate) → insulin + glucose/sodium bicarb/Kayexalate → dialysis',
    'hypokalemia ecg': 'Hypokalemia ECG Changes — U waves (positive deflection after T wave, best seen V2-V3); T wave flattening or inversion; apparent QT prolongation (actually QU prolongation); ST depression; ↑risk arrhythmias, digoxin toxicity; replenish K+ to >4 mEq/L in cardiac patients',

    'atrial fibrillation': 'Atrial Fibrillation — irregularly irregular rhythm; absent P waves replaced by fibrillatory baseline (f waves); ventricular rate varies (60-170 bpm uncontrolled); causes: HTN (MCC), valvular disease (mitral), HF, thyrotoxicosis, alcohol, PE, post-cardiac surgery, OSA; CHA₂DS₂-VASc for stroke risk → anticoagulation; rate control: BB, CCB, digoxin; rhythm control: cardioversion, flecainide, amiodarone, ablation',
    'atrial flutter': "Atrial Flutter — regular sawtooth flutter waves at 300 bpm (F waves); ventricular rate typically 150 bpm (2:1 block) — any regular tachycardia at 150 must consider flutter; type I (typical/CCW): negative flutter waves in II,III,aVF + positive in V1; type II (atypical): >340 bpm; tx: rate control (BB, CCB, digoxin); cardioversion; ablation (cavotricuspid isthmus, ~95% success); anticoagulate same as AF",
    'ventricular tachycardia': 'Ventricular Tachycardia (VT) — 3+ consecutive wide-complex beats at ≥100 bpm; QRS >120ms; monomorphic VT (uniform QRS) vs polymorphic VT (varying QRS — TdP if prolonged QT); causes: structural heart disease (post-MI scar), cardiomyopathy, Brugada, ARVC; distinguishing VT from SVT with aberrancy: AV dissociation (pathognomonic for VT), fusion/capture beats, QRS >160ms, concordance in precordial leads, northwest axis; tx: if unstable → defibrillate; stable → amiodarone; ICD if structural disease',
    'ventricular fibrillation': 'Ventricular Fibrillation — chaotic, irregular wide-complex rhythm; no organized electrical activity; no cardiac output → cardiac arrest; causes: MI (esp. first 48h), cardiomyopathy, electrolyte abnormalities (↓K+, ↓Mg²+), hypothermia, long QT, Brugada, WPW with AF; tx: immediate defibrillation (200J biphasic); CPR; epinephrine 1mg IV q3-5min; amiodarone 300mg IV; identify and treat reversible causes (4H4T); ICD for secondary prevention',
    'svt': "SVT (Supraventricular Tachycardia) — narrow-complex tachycardia (unless aberrant conduction) at 150-250 bpm; AVNRT (MCC, 60%): typical (slow-fast) — retrograde P in QRS or just after; AVRT (30%): WPW — orthodromic (narrow) vs antidromic (wide); atrial tachycardia (10%); vagal maneuvers → adenosine (6mg → 12mg IV rapid push) → cardioversion if unstable; maintenance: BB, CCB, ablation (curative >95%)",
    'wpw': 'Wolff-Parkinson-White Syndrome — pre-excitation via accessory pathway (Bundle of Kent) bypassing AV node; short PR (<120ms) + delta wave (slurred upstroke) + wide QRS + secondary ST-T changes; AVRT: orthodromic (narrow, anterograde through AV node, retrograde via AP) or antidromic (wide, anterograde via AP); AF in WPW: DANGEROUS — avoid adenosine, digoxin, CCBs (block AV node → all conduction via AP → very rapid ventricular rate → VF); tx: ablation (curative); procainamide or cardioversion if AF+WPW',
    'pvcs': 'PVCs (Premature Ventricular Contractions) — early wide QRS complexes (>120ms) without preceding P wave; followed by compensatory pause; causes: electrolyte disturbance, ischemia, stimulants (caffeine, cocaine), cardiomyopathy, normal variant; bigeminy (every other beat), trigeminy (every third); multifocal PVCs (multiple morphologies) suggest cardiac pathology; concerning if: >10% of beats, R-on-T, runs (≥3 = VT); tx: benign PVCs — reassure; symptomatic or high burden — BB; ablation for high-burden PVC cardiomyopathy',
    'junctional rhythm': 'Junctional Rhythm — rhythm arising from AV node/Bundle of His; narrow QRS; rate 40-60 bpm (escape) or 60-100 bpm (accelerated); P waves: absent, retrograde (inverted in II,III,aVF, before/during/after QRS), or dissociated; causes: sinus node dysfunction, increased vagal tone, inferior MI, digoxin toxicity, post-cardiac surgery; accelerated junctional (60-100): digoxin toxicity, inferior MI; tx: treat underlying cause; atropine/pacing if symptomatic bradycardia',
    'pac': 'PAC (Premature Atrial Contraction) — early narrow-complex beat with abnormal (non-sinus) P wave morphology; usually followed by non-compensatory pause; causes: caffeine, alcohol, stimulants, electrolyte disturbances, structural heart disease; typically benign; frequent PACs may trigger AF/flutter; no treatment usually needed; avoid triggers; BB if symptomatic',
    'sinus tachycardia': 'Sinus Tachycardia — regular narrow-complex rhythm >100 bpm with normal P waves before each QRS; causes: fever, pain, anxiety, dehydration, anemia, hyperthyroidism, PE, heart failure, drugs (stimulants, atropine), withdrawal; ALWAYS treat the underlying cause — sinus tachycardia is a response, not a primary arrhythmia; inappropriate sinus tachycardia (IST): persistent resting HR >100 without clear cause — BB or ivabradine',
    'sinus bradycardia': 'Sinus Bradycardia — regular narrow-complex rhythm <60 bpm with normal P waves; causes: athletic conditioning (normal), vagal tone, inferior MI (RCA → SA node), hypothyroidism, hypothermia, ↑ICP, drugs (BB, CCB, digoxin, opioids, clonidine); tx: if asymptomatic → observe; if symptomatic → atropine 1 mg IV (repeat q3-5min, max 3 mg — ACLS 2020) → transcutaneous pacing → dopamine/epinephrine infusion → permanent pacemaker if persistent',
    'sick sinus syndrome': 'Sick Sinus Syndrome (SSS) — dysfunction of SA node producing symptomatic bradycardia, pauses, or tachycardia-bradycardia syndrome; tachy-brady: AF with rapid ventricular rate alternating with sinus pauses; causes: idiopathic fibrosis (elderly), ischemia (RCA/sinus node artery), amyloid, sarcoid, post-surgical; symptoms: syncope, presyncope, palpitations, fatigue; tx: permanent pacemaker (PPM) — DDD mode; anticoagulation if AF component',
    'lgl syndrome': 'Lown-Ganong-Levine (LGL) Syndrome — short PR interval (<120ms) + normal QRS (no delta wave) + SVT; accessory pathway bypasses AV node but connects to Bundle of His (James fibers); pre-excitation without delta wave distinguishes from WPW; associated with SVT/AF; tx: similar to WPW — BB, ablation',
    'long qt syndrome': 'Long QT Syndrome (LQTS) — congenital channelopathy causing QTc prolongation and risk of TdP/SCD; LQT1 (IKs, KCNQ1 — exercise-triggered, swimming): beta blockers effective; LQT2 (IKr, KCNH2 — loud noise/emotion triggered): BB + avoid QT drugs; LQT3 (INa, SCN5A — sleep triggered): mexiletine, Na channel blocker; diagnosis: QTc >470ms (men) or >480ms (women) on resting ECG; Schwartz score; tx: BB (LQT1/2), ICD (high-risk), avoid QT-prolonging drugs',
    'lvh': "Left Ventricular Hypertrophy (ECG) — voltage criteria: Sokolow-Lyon (S in V1 + R in V5 or V6 ≥35 mm) or Cornell (R in aVL + S in V3 >28 mm men, >20 mm women); 'strain' pattern = asymmetric ST depression/T inversion in V5-V6, I, aVL; left axis deviation and left atrial enlargement often coexist; causes: hypertension, aortic stenosis, HCM; ECG is specific but insensitive — echo confirms",
    'rvh': 'Right Ventricular Hypertrophy (ECG) — right axis deviation (>+90°), dominant R in V1 (R/S >1 or R ≥7 mm), deep S in V5-V6, right atrial enlargement (P pulmonale ≥2.5 mm in II), RV strain (ST depression/T inversion V1-V3); causes: pulmonary hypertension, COPD/cor pulmonale, pulmonary stenosis, chronic PE, congenital heart disease; other causes of a tall R in V1: RBBB, posterior MI, WPW (left-sided pathway), dextrocardia',
    'left posterior fascicular block': 'Left Posterior Fascicular Block (LPFB) — right axis deviation (+90° to +180°), rS in I and aVL, qR in II, III, aVF, QRS <120 ms; a diagnosis of exclusion (rule out RVH, lateral MI, PE, lean habitus); rarer than LAFB because the posterior fascicle is broad with a dual blood supply — so LPFB implies extensive conduction disease',
    'bifascicular block': "Bifascicular Block — RBBB + left anterior fascicular block (most common) or RBBB + left posterior fascicular block; conduction depends on the one remaining fascicle; with first-degree AV block it is sometimes called 'trifascicular' (a misnomer); syncope with bifascicular block → look for intermittent high-grade AV block (monitoring/EP study; pace if documented)",
    'wellens syndrome': 'Wellens Syndrome — deep symmetric T-wave inversion (type B) or biphasic T waves (type A) in V2-V3 in a now pain-free patient with recent angina; little or no ST elevation, no Q waves, preserved R-wave progression; indicates critical proximal LAD stenosis with high risk of a large anterior MI — avoid stress testing, needs urgent angiography',
    'de winter t waves': 'de Winter T Waves — upsloping ST depression ≥1 mm at the J point in V1-V6 with tall, symmetric, peaked T waves (often 1-2 mm ST elevation in aVR); a STEMI equivalent of acute proximal LAD occlusion (~2% of anterior MIs) — treat as STEMI (emergent reperfusion)',
    'hyperacute t waves': "Hyperacute T Waves — broad-based, tall, symmetric T waves out of proportion to the QRS in a coronary territory; earliest sign of acute coronary occlusion (minutes), often before ST elevation — repeat the ECG in 15-30 min; differential: hyperkalemia (narrow-based, peaked 'tented' T waves), early repolarization, LVH",
    'u wave': 'U Wave — small positive deflection after the T wave, best seen in V2-V3; prominent U waves: hypokalemia (classic), bradycardia, hypomagnesemia, digoxin, class IA/III antiarrhythmics; inverted U waves: myocardial ischemia or LVH (always abnormal); a U wave fused to the T wave can be mistaken for a long QT (QU interval)',
    'low voltage qrs': 'Low-Voltage QRS — QRS amplitude <5 mm in all limb leads or <10 mm in all precordial leads; causes: pericardial effusion/tamponade (± electrical alternans), obesity, COPD/emphysema, pneumothorax, hypothyroidism (myxedema), infiltrative cardiomyopathy (amyloid — low voltage despite thick walls on echo), large prior MI, anasarca',
    'poor r wave progression': 'Poor R-Wave Progression — R wave ≤3 mm in V3 or failure of R to grow from V1 to V4; causes: prior anterior MI, high lead placement, LVH, LBBB, COPD, dextrocardia, cardiomyopathy, normal variant; nonspecific — correlate with echo',
    'multifocal atrial tachycardia': 'Multifocal Atrial Tachycardia (MAT) — irregular narrow-complex rhythm >100 bpm with ≥3 distinct P-wave morphologies and varying PR intervals; classic in severe COPD/hypoxia, also theophylline, hypokalemia, hypomagnesemia, sepsis; treat the lung disease and correct K+/Mg2+; rate control with verapamil/diltiazem; NOT treated with cardioversion (no single circuit)',
    'accelerated idioventricular rhythm': 'Accelerated Idioventricular Rhythm (AIVR) — regular wide-complex rhythm at 50-110 bpm (faster than a ventricular escape, slower than VT), often with fusion/capture beats; classic reperfusion arrhythmia after thrombolysis or PCI; also digoxin toxicity, cocaine, cardiomyopathy; usually benign and self-limited — do NOT suppress with antiarrhythmics (may leave no rhythm)',
    'asystole': 'Asystole — no electrical activity; confirm in two leads and check gain/connections (rule out fine VF); non-shockable: high-quality CPR + epinephrine 1 mg IV/IO every 3-5 min as soon as possible; treat reversible causes (Hs and Ts: hypovolemia, hypoxia, acidosis, hypo/hyperkalemia, hypothermia; tension pneumothorax, tamponade, toxins, coronary/pulmonary thrombosis); worst prognosis of the arrest rhythms',
    'pulseless electrical activity': 'Pulseless Electrical Activity (PEA) — organized electrical rhythm without a palpable pulse; non-shockable: CPR + epinephrine 1 mg every 3-5 min; outcome depends on finding the cause (Hs and Ts) — narrow-complex PEA suggests mechanical causes (tamponade, tension pneumothorax, massive PE, hypovolemia), wide-complex PEA suggests metabolic causes (hyperkalemia, sodium-channel blocker toxicity, severe acidosis); bedside ultrasound helps',
    'av dissociation': 'AV Dissociation — atria and ventricles beat independently (P waves march through unrelated QRS complexes); a finding, not a diagnosis; causes: complete heart block (atrial rate > ventricular), VT (ventricular rate > atrial — favors VT over SVT with aberrancy), accelerated junctional/idioventricular rhythms; look for fusion and capture beats',
    'fusion beat': "Fusion and Capture Beats — fusion beat: a QRS intermediate in shape from simultaneous sinus and ventricular activation; capture beat: a normal narrow QRS interrupting a wide-complex tachycardia (a sinus impulse briefly 'captures' the ventricles); both indicate AV dissociation and strongly favor ventricular tachycardia over SVT with aberrancy",
    'hypercalcemia ecg': 'Hypercalcemia (ECG) — short QT interval (shortened ST segment), J (Osborn-like) waves when severe, bradycardia and AV block; very high Ca2+ can cause VF; potentiates digoxin toxicity',
    'hypocalcemia ecg': 'Hypocalcemia (ECG) — QT prolongation from a lengthened ST segment (T wave itself normal); can precipitate torsades de pointes; causes: hypoparathyroidism, vitamin D deficiency, CKD, massive transfusion (citrate), pancreatitis, hypomagnesemia; contrast hypokalemia (flat T + U waves)',
    'tca overdose ecg': 'Tricyclic Antidepressant Overdose (ECG) — sinus tachycardia, QRS widening (>100 ms predicts seizures; >160 ms ventricular arrhythmias), terminal R wave in aVR >3 mm, rightward terminal QRS axis, QT prolongation; sodium-channel blockade → IV sodium bicarbonate (target pH 7.45-7.55)',
    'qtc': 'Corrected QT (QTc) — QT adjusted for heart rate; Bazett: QTc = QT / √RR (seconds) — overcorrects at fast rates; Fridericia (QT / ∛RR) is more accurate at extremes; prolonged: >450 ms men, >460-470 ms women; >500 ms = high torsades risk (stop QT-prolonging drugs, replace K+ and Mg2+); short QT <340-360 ms (short QT syndrome, hypercalcemia, digoxin)',
    'left axis deviation': 'Left Axis Deviation — QRS axis −30° to −90° (positive in I, negative in II and aVF); causes: left anterior fascicular block (most common), inferior MI, LBBB, LVH, WPW, ventricular pacing, primum ASD, hyperkalemia; quick check: lead I up + lead II down',
    'right axis deviation': 'Right Axis Deviation — QRS axis +90° to +180° (negative in I, positive in aVF); causes: RVH, acute PE/right heart strain, COPD, lateral MI, left posterior fascicular block, dextrocardia, limb-lead reversal; normal in children and tall thin adults; quick check: lead I down + aVF up',
    'ashman phenomenon': 'Ashman Phenomenon — an aberrantly conducted beat (usually RBBB shape) in AF when a short R-R interval follows a long one (long-short sequence): the long cycle lengthens the bundle refractory period, so the next early impulse finds the right bundle still refractory; benign — do not mistake for PVCs or VT',
    'second degree av block': 'Second-Degree AV Block — some P waves are not conducted; Mobitz I (Wenckebach): progressive PR prolongation before a dropped beat, usually AV-nodal and benign (inferior MI, vagal tone, drugs); Mobitz II: constant PR with sudden dropped beats, infranodal (His-Purkinje), often wide QRS — risk of complete heart block → pacemaker; 2:1 block cannot be classified from one strip',
}
